/** Optimised client photography (generated by scripts/process_assets.py). */
export type Media = {
  base: string;
  widths: number[];
  w: number; // largest width
  h: number; // largest height
  alt: string;
  source: string; // original client filename
};

const m = (base: string, widths: number[], h: number, alt: string, source: string): Media => ({
  base,
  widths,
  w: widths[widths.length - 1],
  h,
  alt,
  source,
});

